package edu.curtin.game;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.text.Normalizer;
import java.util.*;

import org.antlr.v4.runtime.*;
import org.antlr.v4.runtime.tree.TerminalNode;
import org.python.core.PyException;
import org.python.util.PythonInterpreter;

import edu.curtin.api.*;
import edu.curtin.game.parser.GameConfigLexer;
import edu.curtin.game.parser.GameConfigParser;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.format.FormatStyle;

public class PuzzleGame implements GameAPI {
    private int rows, cols;
    private int playerRow, playerCol;
    // private int goalRow, goalCol;
    private Cell[][] grid;
    private Set<String> inventory;
    private Scanner scanner;
    private Locale currentLocale;
    private ResourceBundle messages;
    private LocalDate gameDate;
    private int moveCount;

    private List<MoveCallback> moveCallbacks;
    private List<ItemCallback> itemCallbacks;
    private Map<String, MenuCallback> menuCallbacks;
    private List<ObstacleCallback> obstacleCallbacks;
    private String lastAcquiredItem;

    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println("Usage: java PuzzleGame <config-file>");
            return;
        }

        PuzzleGame game = new PuzzleGame();
        try {
            // load from file
            game.loadConfig(args[0]);
            game.play();
        } catch (IOException e) {
            System.out.println("Error reading file: " + e.getMessage());
        }
    }

    // initialize game state and callbacks
    public PuzzleGame() {
        inventory = new HashSet<>();
        scanner = new Scanner(System.in);
        currentLocale = Locale.getDefault();
        messages = ResourceBundle.getBundle("bundle", currentLocale);
        gameDate = LocalDate.now();
        moveCount = 0;

        moveCallbacks = new ArrayList<>();
        itemCallbacks = new ArrayList<>();
        menuCallbacks = new LinkedHashMap<>();
        obstacleCallbacks = new ArrayList<>();
        lastAcquiredItem = null;
    }

    // ================ GameAPI Implementation==================

    // register Callback when player makes a move
    @Override
    public void registerMoveCallback(MoveCallback callback) {
        moveCallbacks.add(callback);
    }

    // register Callback when player acquires an item
    @Override
    public void registerItemCallback(ItemCallback callback) {
        itemCallbacks.add(callback);
    }

    // register Callback when player selects a menu option
    @Override
    public void registerMenuOption(String label, MenuCallback callback) {
        menuCallbacks.put(label, callback);
    }

    // register Callback when player go through an obstacle
    @Override
    public void registerObstacleCallback(ObstacleCallback callback) {
        obstacleCallbacks.add(callback);
    }

    // Get PLAYER'S Row
    @Override
    public int getPlayerRow() {
        return playerRow;
    }

    // Get PLAYER'S Column
    @Override
    public int getPlayerCol() {
        return playerCol;
    }

    // Set player location and reveal surrounding cells
    @Override
    public void setPlayerLocation(int row, int col) {
        if (isValid(row, col)) {
            playerRow = row;
            playerCol = col;
            revealSurrounding(row, col);
        }
    }

    // Get a copy of the player's inventory
    @Override
    public Set<String> getInventory() {
        return new HashSet<>(inventory);
    }

    // Get the last acquired item
    @Override
    public String getLastAcquiredItem() {
        return lastAcquiredItem;
    }

    // Add an item to the player's inventory
    @Override
    public void addItemToInventory(String itemName) {
        inventory.add(itemName);
        lastAcquiredItem = itemName;
    }

    // Remove an item from the player's inventory
    @Override
    public void removeItemFromInventory(String itemName) {
        inventory.remove(itemName);
    }

    // Get number of rows in the grid
    @Override
    public int getRows() {
        return rows;
    }

    // Get number of columns in the grid
    @Override
    public int getCols() {
        return cols;
    }

    // Get the item at a specific location
    @Override
    public String getItemAt(int row, int col) {
        if (isValid(row, col)) {
            return grid[row][col].getItem();
        }
        return null;
    }

    // Get the requirements for all obstacles in the grid
    @Override
    public List<String> getObstacleRequirements() {
        List<String> allRequirements = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j].hasObstacle()) {
                    allRequirements.addAll(grid[i][j].getRequiredItems());
                }
            }
        }
        return allRequirements;
    }

    // Get the requirements for the obstacle at a specific location
    @Override
    public List<String> getObstacleRequirementsAt(int row, int col) {
        if (isValid(row, col) && grid[row][col].hasObstacle()) {
            return new ArrayList<>(grid[row][col].getRequiredItems());
        }
        return null;
    }

    // Check if there is an obstacle at a specific location
    @Override
    public boolean isObstacleAt(int row, int col) {
        return isValid(row, col) && grid[row][col].hasObstacle();
    }

    // Check if there is a goal at a specific location
    @Override
    public boolean isGoalAt(int row, int col) {
        return isValid(row, col) && grid[row][col].isGoal();
    }

    // Check if a cell is visible at a specific location
    @Override
    public boolean isVisibleAt(int row, int col) {
        return isValid(row, col) && grid[row][col].isVisible();
    }

    // Set the visibility of a cell at a specific location
    @Override
    public void setVisibleAt(int row, int col, boolean visible) {
        if (isValid(row, col)) {
            grid[row][col].setVisible(visible);
        }
    }

    // Add an obstacle at a specific location
    @Override
    public void addObstacleAt(int row, int col, List<String> requirements) {
        if (isValid(row, col)) {
            grid[row][col].setObstacle(new ArrayList<>(requirements));
        }
    }

    // Remove an obstacle at a specific location
    @Override
    public void removeObstacleAt(int row, int col) {
        if (isValid(row, col)) {
            grid[row][col].setObstacle(null);
        }
    }

    // Add an item at a specific location
    @Override
    public void addItemAt(int row, int col, String itemName) {
        if (isValid(row, col) && grid[row][col].getItem() == null && !grid[row][col].hasObstacle()) {
            grid[row][col].setItem(itemName, null);
        }
    }

    // Remove an item at a specific location
    @Override
    public void removeItemAt(int row, int col) {
        if (isValid(row, col)) {
            grid[row][col].removeItem();
        }
    }

    // Add a goal at a specific location
    @Override
    public void addGoalAt(int row, int col) {
        if (isValid(row, col)) {
            grid[row][col].setGoal(true);
        }
    }

    // Remove a goal at a specific location
    @Override
    public void removeGoalAt(int row, int col) {
        if (isValid(row, col)) {
            grid[row][col].setGoal(false);
        }
    }

    // ================ End of GameAPI Implementation==================

    // Load the game configuration from a file
    private void loadConfig(String filename) throws IOException {
        Charset charset = determineCharset(filename);
        CharStream input = CharStreams.fromFileName(filename, charset);

        // Create a lexer and parser for the game configuration
        GameConfigLexer lexer = new GameConfigLexer(input);
        CommonTokenStream tokens = new CommonTokenStream(lexer);
        GameConfigParser parser = new GameConfigParser(tokens);

        GameConfigParser.ConfigContext configCtx = parser.config();

        // Process each declaration in the configuration
        for (GameConfigParser.DeclarationContext declCtx : configCtx.declaration()) {

            if (declCtx.sizeDecl() != null) {
                // Initialize grid size
                GameConfigParser.CoordContext coord = declCtx.sizeDecl().coord();
                // Get the number of rows and columns
                rows = (Integer.parseInt(coord.INT(0).getText())) + 1;
                cols = (Integer.parseInt(coord.INT(1).getText())) + 1;

                // Create the grid and initialize cells
                grid = new Cell[rows][cols];
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = new Cell();
                    }
                }
            } else if (declCtx.startDecl() != null) {
                // Set player starting position
                GameConfigParser.CoordContext coord = declCtx.startDecl().coord();
                playerRow = Integer.parseInt(coord.INT(0).getText());
                playerCol = Integer.parseInt(coord.INT(1).getText());

            } else if (declCtx.goalDecl() != null) {
                int goalRow, goalCol;

                // Set goal position
                GameConfigParser.CoordContext coord = declCtx.goalDecl().coord();
                goalRow = Integer.parseInt(coord.INT(0).getText());
                goalCol = Integer.parseInt(coord.INT(1).getText());
                grid[goalRow][goalCol].setGoal(true);

            } else if (declCtx.itemDecl() != null) {
                // Place items on the grid
                String itemName = unquote(declCtx.itemDecl().STRING().getSymbol());

                String message = null;
                GameConfigParser.MessageClauseContext msgCtx = declCtx.itemDecl().itemBody().messageClause();
                if (msgCtx != null) {
                    message = unquote(msgCtx.STRING().getSymbol());
                }

                for (GameConfigParser.CoordContext coord : declCtx.itemDecl().itemBody().atClause().coordList()
                        .coord()) {
                    int row = Integer.parseInt(coord.INT(0).getText());
                    int col = Integer.parseInt(coord.INT(1).getText());
                    grid[row][col].setItem(itemName, message);
                }

            } else if (declCtx.obstacleDecl() != null) {
                // Place obstacles on the grid
                List<String> requiredItems = new ArrayList<>();

                // Get required items for the obstacle
                for (TerminalNode stringNode : declCtx.obstacleDecl().obstacleBody().requiresClause().stringList()
                        .STRING()) {
                    requiredItems.add(unquote(stringNode.getSymbol()));
                }

                for (GameConfigParser.CoordContext coord : declCtx.obstacleDecl().obstacleBody().atClause().coordList()
                        .coord()) {
                    int row = Integer.parseInt(coord.INT(0).getText());
                    int col = Integer.parseInt(coord.INT(1).getText());
                    grid[row][col].setObstacle(new ArrayList<>(requiredItems));
                }
            } else if (declCtx.pluginDecl() != null) {
                // Load the plugin
                loadPlugin(declCtx.pluginDecl());

            } else if (declCtx.scriptDecl() != null) {
                // Load and execute the script
                loadScript(declCtx.scriptDecl());
            }
        }

        // Reveal cells surrounding the player's starting position
        revealSurrounding(playerRow, playerCol);
        // Make the player starting cell visible
        grid[playerRow][playerCol].setVisible(true);

    }

    // Load and initialize a plugin
    private void loadPlugin(GameConfigParser.PluginDeclContext ctx) {
        StringBuilder className = new StringBuilder();
        List<TerminalNode> identifiers = ctx.IDENTIFIER();
        for (int i = 0; i < identifiers.size(); i++) {
            // Build the fully qualified class name
            if (i > 0) {
                className.append(".");
            }
            className.append(identifiers.get(i).getText());
        }

        try {
            // Dynamically load and instantiate the plugin class
            Class<?> pluginClass = Class.forName(className.toString());
            Plugin plugin = (Plugin) pluginClass.getDeclaredConstructor().newInstance();
            // Initialize the plugin with the GameAPI
            plugin.initialize(this);
        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException
                | InvocationTargetException e) {
            System.err.println("Failed to load plugin: " + className + " - " + e.getMessage());
        }
    }

    // Load and execute a script
    private void loadScript(GameConfigParser.ScriptDeclContext ctx) {
        String scriptText = ctx.SCRIPT().getText();
        scriptText = scriptText.substring(2, scriptText.length() - 1); // Remove !{ and }

        try (PythonInterpreter interpreter = new PythonInterpreter()) {
            // Execute the script using Jython
            interpreter.set("api", this);
            interpreter.exec(scriptText);
        } catch (PyException e) {
            System.err.println("Failed to execute script: " + e.getMessage());
        }
    }

    // Remove quotes from a STRING token
    private String unquote(Token token) {
        String text = token.getText();

        // Remove the surrounding quotes
        return text.substring(1, text.length() - 1);
    }

    // Determine the charset based on the file extension
    private Charset determineCharset(String filename) {
        if (filename.endsWith(".utf8.map")) {
            return StandardCharsets.UTF_8;
        } else if (filename.endsWith(".utf16.map")) {
            return StandardCharsets.UTF_16;
        } else if (filename.endsWith(".utf32.map")) {
            return Charset.forName("UTF-32");
        } else {
            return StandardCharsets.UTF_8;
        }
    }

    // Change the current locale based on user input
    private void changeLocale() {
        System.out.println();
        System.out.println(messages.getString("enterLocale"));
        String localeStr = scanner.nextLine().trim();
        currentLocale = Locale.forLanguageTag(localeStr);
        messages = ResourceBundle.getBundle("bundle", currentLocale);
        System.out.println();
        System.out.println(messages.getString("localeChanged") + currentLocale.getDisplayLanguage());
    }

    // Reveal cells surrounding a given cell
    private void revealSurrounding(int row, int col) {
        int[][] directions = { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } };
        for (int[] dir : directions) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];
            if (isValid(newRow, newCol)) {
                grid[newRow][newCol].setVisible(true);
            }
        }
    }

    // Check if a cell position is in valid range
    private boolean isValid(int row, int col) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    // Main game loop
    private void play() {
        System.out.println();
        System.out.println(messages.getString("welcome"));
        System.out.println(messages.getString("commands"));

        while (true) {
            displayDate();
            displayGrid();
            System.out.println(messages.getString("inventory") + inventory);

            // Display menu options if any
            if (!menuCallbacks.isEmpty()) {
                System.out.println("Menu options:");
                int i = 1;
                // List menu options
                for (String label : menuCallbacks.keySet()) {
                    System.out.println(i + ". " + label);
                    i++;
                }
            }

            System.out.print(messages.getString("enterCommand"));

            String command = scanner.nextLine().trim().toLowerCase();

            if (command.equals("quit")) {
                System.out.println();
                System.out.println(messages.getString("gameEnded"));
                break;
            }

            if (command.equals("locale")) {
                System.out.println();
                changeLocale();
                continue;
            }

            // Check menu options
            try {
                int menuChoice = Integer.parseInt(command);
                if (menuChoice > 0 && menuChoice <= menuCallbacks.size()) {
                    String[] labels = menuCallbacks.keySet().toArray(new String[0]);
                    menuCallbacks.get(labels[menuChoice - 1]).onMenuSelected();
                    continue;
                }
            } catch (NumberFormatException e) {
                // Not a number, continue with movement
                System.out.println();
            }

            int newRow = playerRow;
            int newCol = playerCol;

            // Process movement commands
            switch (command) {
                case "w":
                    newRow--;
                    break;
                case "s":
                    newRow++;
                    break;
                case "a":
                    newCol--;
                    break;
                case "d":
                    newCol++;
                    break;
                default:
                    System.out.println();
                    System.out.println(messages.getString("invalidCommand"));
                    continue;
            }

            if (!isValid(newRow, newCol)) {
                System.out.println();
                System.out.println(messages.getString("cannotMove"));
                continue;
            }

            Cell targetCell = grid[newRow][newCol];

            // Check for obstacles
            if (targetCell.hasObstacle()) {
                List<String> required = targetCell.getRequiredItems();
                boolean hasAll = hasRequiredItems(required);

                if (!hasAll) {
                    System.out.println();
                    System.out.println(messages.getString("cannotPass") + required);
                    continue;
                }
                // Notify obstacle callbacks if obstacle is traversed
                for (ObstacleCallback callback : obstacleCallbacks) {
                    callback.onObstacleTraversed();
                }
            }

            // Move the player
            playerRow = newRow;
            playerCol = newCol;
            moveCount++;

            // Advance the game date by one day
            gameDate = gameDate.plusDays(1);

            // Notify move callbacks
            for (MoveCallback callback : moveCallbacks) {
                callback.onMove(command);
            }

            // Reveal surrounding cells at new position
            revealSurrounding(playerRow, playerCol);

            // Check for item pickup
            if (targetCell.hasItem()) {
                String item = targetCell.getItem();
                String itemMsg = targetCell.getItemMessage();
                inventory.add(item);
                System.out.println();
                System.out.println(messages.getString("pickedUp") + item);
                if (itemMsg != null) {
                    System.out.println(itemMsg);
                }

                // Notify item callbacks
                for (ItemCallback callback : itemCallbacks) {
                    callback.onItemAcquired(item);
                }

                // Remove the item from the cell
                targetCell.removeItem();
            }

            // Check for goal achievement
            if (targetCell.isGoal()) {
                displayGrid();
                displayDate();
                System.out.println();
                System.out.println(messages.getString("congratulations"));
                System.out.println(messages.getString("daysElapsed") + moveCount);
                break;
            }
        }
    }

    // Check if the player has all required items (normalized)
    private boolean hasRequiredItems(List<String> required) {
        List<String> normRequiredList = new ArrayList<>();
        Set<String> normInventory = new HashSet<>();
        for (String item : required) {
            String normalizedItem = Normalizer.normalize(item, Normalizer.Form.NFKC);
            normRequiredList.add(normalizedItem);
        }
        for (String invItem : inventory) {
            String normalizedInvItem = Normalizer.normalize(invItem, Normalizer.Form.NFKC);
            normInventory.add(normalizedInvItem);
        }
        return normInventory.containsAll(normRequiredList);
    }

    // Display the current game date
    private void displayDate() {
        DateTimeFormatter formatter = DateTimeFormatter.ofLocalizedDate(FormatStyle.FULL).withLocale(currentLocale);

        System.out.println();
        System.out.println(messages.getString("date") + gameDate.format(formatter));
    }

    // Display the game grid
    @SuppressWarnings("PMD.ConfusingTernary")
    private void displayGrid() {
        System.out.println();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (i == playerRow && j == playerCol) {
                    System.out.print(" P ");
                } else if (!grid[i][j].isVisible()) {
                    System.out.print(" # ");
                } else if (grid[i][j].isGoal()) {
                    System.out.print(" G ");
                } else if (grid[i][j].hasItem()) {
                    System.out.print(" I ");
                } else if (grid[i][j].hasObstacle()) {
                    System.out.print(" X ");
                } else {
                    System.out.print(" . ");
                }
            }
            System.out.println();
        }
        System.out.println();
    }
}
